bool _defaultSpellsRecord(String id, String baseUrl) {
  final bare = resolveCliProviderSpec(id);
  if (bare == null || bare.defaultBaseUrl.isEmpty) return false;
  return sameEndpoint(bare.defaultBaseUrl, baseUrl);
