void _revalidatePartialOverride(
  CliArgs parsed,
  EnvProviderPreconfig? faPreconfig,
  CliConfig saved, {
  required String provider,
  required String baseUrl,
  required bool keepSavedPair,
  required String? degradedDefault,
}) {
