        ? '$host:$port'
        : host;
    return _dedupe(candidate);
  }

  String _dedupe(String candidate) {
    final reserved = <String>{'custom', ...providerCatalog.keys};
    var name = candidate;
    var suffix = 2;
    while (reserved.contains(name) || find(name) != null) {
      name = '$candidate-${suffix++}';
    }
    return name;
