Set<String> roleKeyNames(ModelRolesConfig rolesConfig) {
  final refs = [
    for (final chain in rolesConfig.roles.values) ...chain,
    for (final override in rolesConfig.pathOverrides)
      for (final chain in override.roles.values) ...chain,
  ];
