/// Boot-time migration of stranded key slots (gh-1570 incident ...):
/// for every known endpoint/record pair, when the canonical slot is
/// empty and a legacy cross-spelling slot holds a value, COPY the value
/// onto the canonical slot (non-destructive — the legacy slot stays) and
/// return a notice line per move. [endpoints] are the (baseUrl,
/// providerName?) pairs the boot knows: the saved custom registry's
/// entries plus the roles config's custom-endpoint chain refs. Keychain
/// explicitly in scope: [keys].save writes through to the OS store.
Future<List<String>> migrateLegacyKeySlots({
  required Iterable<(String, String?)> endpoints,
  required SecureKeyCache keys,
}) async {
  final notices = <String>[];
  if (!keys.available) return notices;
