    // already a suffix of the host slug, e.g. an entry named 'z.ai' on
    // api.z.ai (gh-1226 AC3) — must not double the suffix:
    // FA_KEY_API_AIIN_BY / FA_KEY_API_Z_AI, not ..._API_AIIN_BY /
    // ..._Z_AI_Z_AI.
    return name == null ||
            name.isEmpty ||
            name == sanitized ||
