  /// its scheme derives the host-only slot (`FA_KEY_API_KIMI_COM`) —
  /// exactly the 1.0.556 → 1.0.564 lockout. Canonical first; never empty.
  static List<String> keySlotCandidates(String baseUrl, {String? providerName}) {
    final candidates = <String>[keyNameFor(baseUrl, providerName: providerName)];
