      // entry finds no key anywhere (the helper's OPENAI_API_KEY=mock
      // pin must not leak onto kimi's env-name chain).
      final result = await runFa(
        'say something',
        extraEnv: const {'KIMI_API_KEY': '', 'OPENAI_API_KEY': ''},
      );

